-- ----------------------------
-- Table structure for ClientExtensionEntry
-- ----------------------------
DROP TABLE IF EXISTS `ClientExtensionEntry`;
CREATE TABLE `ClientExtensionEntry`  (
  `mvccVersion` bigint NOT NULL DEFAULT 0,
  `ctCollectionId` bigint NOT NULL DEFAULT 0,
  `uuid_` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `externalReferenceCode` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `clientExtensionEntryId` bigint NOT NULL,
  `companyId` bigint NULL DEFAULT NULL,
  `userId` bigint NULL DEFAULT NULL,
  `userName` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `createDate` datetime(6) NULL DEFAULT NULL,
  `modifiedDate` datetime(6) NULL DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `name` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `properties` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `sourceCodeURL` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `type_` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `typeSettings` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `status` int NULL DEFAULT NULL,
  `statusByUserId` bigint NULL DEFAULT NULL,
  `statusByUserName` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `statusDate` datetime(6) NULL DEFAULT NULL,
  PRIMARY KEY (`clientExtensionEntryId`, `ctCollectionId`) USING BTREE,
  UNIQUE INDEX `IX_EFD3CBF7`(`companyId`, `externalReferenceCode`, `ctCollectionId`) USING BTREE,
  INDEX `IX_93662B82`(`companyId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_CD38508F`(`companyId`, `type_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_9E207BD6`(`uuid_`, `companyId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_C85B970E`(`uuid_`, `ctCollectionId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci;

