-- ----------------------------
-- Table structure for DDMTemplate
-- ----------------------------
DROP TABLE IF EXISTS `DDMTemplate`;
CREATE TABLE `DDMTemplate`  (
  `mvccVersion` bigint NOT NULL DEFAULT 0,
  `ctCollectionId` bigint NOT NULL DEFAULT 0,
  `uuid_` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `templateId` bigint NOT NULL,
  `groupId` bigint NULL DEFAULT NULL,
  `companyId` bigint NULL DEFAULT NULL,
  `userId` bigint NULL DEFAULT NULL,
  `userName` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `versionUserId` bigint NULL DEFAULT NULL,
  `versionUserName` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `createDate` datetime(6) NULL DEFAULT NULL,
  `modifiedDate` datetime(6) NULL DEFAULT NULL,
  `classNameId` bigint NULL DEFAULT NULL,
  `classPK` bigint NULL DEFAULT NULL,
  `resourceClassNameId` bigint NULL DEFAULT NULL,
  `templateKey` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `version` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `name` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `description` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `type_` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `mode_` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `language` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `script` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `cacheable` tinyint NULL DEFAULT NULL,
  `smallImage` tinyint NULL DEFAULT NULL,
  `smallImageId` bigint NULL DEFAULT NULL,
  `smallImageURL` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `lastPublishDate` datetime(6) NULL DEFAULT NULL,
  PRIMARY KEY (`templateId`, `ctCollectionId`) USING BTREE,
  UNIQUE INDEX `IX_ED2AF9E2`(`groupId`, `classNameId`, `templateKey`, `ctCollectionId`) USING BTREE,
  UNIQUE INDEX `IX_147A0D41`(`uuid_`, `groupId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_3A6CBFF1`(`classNameId`, `classPK`, `type_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_40E22774`(`classPK`, `ctCollectionId`) USING BTREE,
  INDEX `IX_492F3DCB`(`ctCollectionId`) USING BTREE,
  INDEX `IX_2A228ED0`(`groupId`, `classNameId`, `classPK`, `ctCollectionId`) USING BTREE,
  INDEX `IX_25F23981`(`groupId`, `classNameId`, `classPK`, `type_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_8DFF58A7`(`groupId`, `classNameId`, `classPK`, `type_`, `mode_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_A967DEEF`(`groupId`, `classNameId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_D3180904`(`groupId`, `classPK`, `ctCollectionId`) USING BTREE,
  INDEX `IX_EFDA5A3B`(`groupId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_3EE9B9D7`(`language`, `ctCollectionId`) USING BTREE,
  INDEX `IX_13A3AC0E`(`smallImageId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_F365A086`(`templateKey`, `ctCollectionId`) USING BTREE,
  INDEX `IX_27ACCA26`(`type_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_C64F367F`(`uuid_`, `companyId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_17F6EC05`(`uuid_`, `ctCollectionId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci;

