  `createDate` datetime(6) NULL DEFAULT NULL,
  `modifiedDate` datetime(6) NULL DEFAULT NULL,
  `kaleoDefinitionId` bigint NULL DEFAULT NULL,
  `name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `title` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `description` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
