  INDEX `IX_15AD2A1B`(`companyId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_9A359A1A`(`companyId`, `name`, `ctCollectionId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci;

