-- ----------------------------
-- Table structure for Release_
-- ----------------------------
DROP TABLE IF EXISTS `Release_`;
CREATE TABLE `Release_`  (
  `mvccVersion` bigint NOT NULL DEFAULT 0,
  `releaseId` bigint NOT NULL,
  `createDate` datetime(6) NULL DEFAULT NULL,
  `modifiedDate` datetime(6) NULL DEFAULT NULL,
  `servletContextName` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `schemaVersion` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `buildNumber` int NULL DEFAULT NULL,
  `buildDate` datetime(6) NULL DEFAULT NULL,
  `verified` tinyint NULL DEFAULT NULL,
  `state_` int NULL DEFAULT NULL,
  `testString` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`releaseId`) USING BTREE,
  UNIQUE INDEX `IX_8BD6BCA7`(`servletContextName`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci;

