-- ----------------------------
-- Table structure for Role_
-- ----------------------------
DROP TABLE IF EXISTS `Role_`;
CREATE TABLE `Role_`  (
  `mvccVersion` bigint NOT NULL DEFAULT 0,
  `ctCollectionId` bigint NOT NULL DEFAULT 0,
  `uuid_` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `roleId` bigint NOT NULL,
  `companyId` bigint NULL DEFAULT NULL,
  `userId` bigint NULL DEFAULT NULL,
  `userName` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `createDate` datetime(6) NULL DEFAULT NULL,
  `modifiedDate` datetime(6) NULL DEFAULT NULL,
  `classNameId` bigint NULL DEFAULT NULL,
  `classPK` bigint NULL DEFAULT NULL,
  `name` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `title` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `description` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `type_` int NULL DEFAULT NULL,
  `subtype` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`roleId`, `ctCollectionId`) USING BTREE,
  UNIQUE INDEX `IX_C0F6BCAC`(`companyId`, `classNameId`, `classPK`, `ctCollectionId`) USING BTREE,
  UNIQUE INDEX `IX_4CC99816`(`companyId`, `name`, `ctCollectionId`) USING BTREE,
  INDEX `IX_4EA65517`(`companyId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_7037255A`(`companyId`, `type_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_B482E6EC`(`name`, `ctCollectionId`) USING BTREE,
  INDEX `IX_18A86359`(`subtype`, `ctCollectionId`) USING BTREE,
  INDEX `IX_FFA7B144`(`type_`, `ctCollectionId`) USING BTREE,
  INDEX `IX_D8DA3062`(`type_`, `subtype`, `ctCollectionId`) USING BTREE,
  INDEX `IX_411F50A1`(`uuid_`, `companyId`, `ctCollectionId`) USING BTREE,
  INDEX `IX_EFF1D323`(`uuid_`, `ctCollectionId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci;

