-- Records of Role_
-- ----------------------------
BEGIN;
INSERT INTO `Role_` (`mvccVersion`, `ctCollectionId`, `uuid_`, `roleId`, `companyId`, `userId`, `userName`, `createDate`, `modifiedDate`, `classNameId`, `classPK`, `name`, `title`, `description`, `type_`, `subtype`) VALUES (0, 0, '6e1661bc-1c6d-7e11-155a-11ad5b363847', 20103, 20097, 20101, NULL, '2022-12-22 04:00:35.500000', '2022-12-22 04:00:35.500000', 20065, 20103, 'Administrator', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Administrators are super users who can do anything.</Description></root>', 1, NULL), (0, 0, '62065142-3f40-4883-75d5-2e3afd1243ed', 20104, 20097, 20101, NULL, '2022-12-22 04:00:35.513000', '2022-12-22 04:00:35.513000', 20065, 20104, 'Analytics Administrator', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Analytics Administrators are users who can view data across the company but cannot make changes except to the company preferences.</Description></root>', 1, NULL), (0, 0, '2787ab92-aee6-f48f-804b-18a9e474ad3c', 20105, 20097, 20101, NULL, '2022-12-22 04:00:35.543000', '2022-12-22 04:00:35.543000', 20065, 20105, 'Guest', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Unauthenticated users always have this role.</Description></root>', 1, NULL), (0, 0, 'b69dd15a-7328-4729-5675-51c54c5cdacc', 20106, 20097, 20101, NULL, '2022-12-22 04:00:35.546000', '2022-12-22 04:00:35.546000', 20065, 20106, 'Owner', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">This is an implied role with respect to the objects users create.</Description></root>', 1, NULL), (0, 0, 'e386a771-8125-918b-39da-8a8c482fe5ab', 20107, 20097, 20101, NULL, '2022-12-22 04:00:35.548000', '2022-12-22 04:00:35.548000', 20065, 20107, 'Power User', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Power Users have their own personal site.</Description></root>', 1, NULL), (0, 0, '3becfb6b-2812-29eb-7cee-562e8af39c8f', 20108, 20097, 20101, NULL, '2022-12-22 04:00:35.550000', '2022-12-22 04:00:35.550000', 20065, 20108, 'Publications User', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Publications Users are users who can access the Publications portlet.</Description></root>', 1, NULL), (0, 0, '749acded-d754-a366-4811-f27be7e50e02', 20109, 20097, 20101, NULL, '2022-12-22 04:00:35.554000', '2022-12-22 04:00:35.554000', 20065, 20109, 'User', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Authenticated users should be assigned this role.</Description></root>', 1, NULL), (0, 0, '52d33da6-fbe6-e080-338f-b9f913cb7e65', 20110, 20097, 20101, NULL, '2022-12-22 04:00:35.566000', '2022-12-22 04:00:35.566000', 20065, 20110, 'Organization Administrator', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Organization Administrators are super users of their organization but cannot make other users into Organization Administrators.</Description></root>', 3, NULL), (0, 0, '2dc16767-977e-ee5f-032a-ab19c5f375cb', 20111, 20097, 20101, NULL, '2022-12-22 04:00:35.568000', '2022-12-22 04:00:35.568000', 20065, 20111, 'Organization Owner', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Organization Owners are super users of their organization and can assign organization roles to users.</Description></root>', 3, NULL), (0, 0, 'b278d877-4833-7e8f-35c8-4ab8cbfd2202', 20112, 20097, 20101, NULL, '2022-12-22 04:00:35.570000', '2022-12-22 04:00:35.570000', 20065, 20112, 'Organization User', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">All users who belong to an organization have this role within that organization.</Description></root>', 3, NULL), (0, 0, 'ddeecccd-3bbc-e13d-37e3-682539106f38', 20113, 20097, 20101, NULL, '2022-12-22 04:00:35.573000', '2022-12-22 04:00:35.573000', 20065, 20113, 'Site Administrator', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Site Administrators are super users of their site but cannot make other users into Site Administrators.</Description></root>', 2, NULL), (0, 0, 'bfccf959-9486-91f5-febf-186d33e57e6b', 20114, 20097, 20101, NULL, '2022-12-22 04:00:35.575000', '2022-12-22 04:00:35.575000', 20065, 20114, 'Site Member', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">All users who belong to a site have this role within that site.</Description></root>', 2, NULL), (0, 0, 'aa9e47f4-f7fb-cff9-cf10-5c835f769c5a', 20115, 20097, 20101, NULL, '2022-12-22 04:00:35.577000', '2022-12-22 04:00:35.577000', 20065, 20115, 'Site Owner', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Site Owners are super users of their site and can assign site roles to users.</Description></root>', 2, NULL), (0, 0, '013021fd-1476-75a9-a268-99d310e32181', 20139, 20097, 20101, NULL, '2022-12-22 04:00:36.571000', '2022-12-22 04:00:36.571000', 20065, 20139, 'Asset Library Administrator', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Administratörer av tillgångsbibliotek är superanvändare av sitt tillgångsbibliotek, men kan inte göra andra användare till administratörer i tillgångsbiblioteket.</Description><Description language-id=\"pt_BR\">Os Administradores da Biblioteca de Ativos são super usuários da biblioteca de ativos, mas não podem tornar outros usuários Administradores da Biblioteca de Ativos.</Description><Description language-id=\"ja_JP\">アセットライブラリの管理者はそれぞれのアセットライブラリのスーパーユーザーですが、他のユーザーをアセットライブラリの管理者にすることはできません。</Description><Description language-id=\"fr_FR\">Les administrateurs d\'un dépôt sont des super utilisateurs de leur dépôt, mais ne peuvent rendre administrateurs d\'autres utilisateurs.</Description><Description language-id=\"hu_HU\">Az adattár adminisztrátorai adattáruk magasabbrendű felhasználói, de nem nevezhetnek ki más felhasználókat az adattár adminisztrátoraivá.</Description><Description language-id=\"de_DE\">Repository-Administratoren sind Administratoren ihres Repositorys, können aber andere Benutzer nicht zu Repository-Administratoren machen.</Description><Description language-id=\"ca_ES\">Els administradors de la biblioteca de continguts són superusuaris de la seva biblioteca de continguts, però no poden assignar el rol d\'administrador de biblioteca de continguts a altres usuaris.</Description><Description language-id=\"ar_SA\">مسؤولو مكتبة الأصول هم مستخدمون متميزون لمكتبة الأصول الخاصة بهم ولكن لا يمكنهم تعيين مستخدمين آخرين كمسئولين لمكتبة الأصول.</Description><Description language-id=\"fi_FI\">Sisältökirjaston Pääkäyttäjät ovat sisältökirjastonsa superkäyttäjiä, mutta eivät voi tehdä muista käyttäjistä Sisältökirjaston Pääkäyttäjiä.</Description><Description language-id=\"en_US\">Asset Library Administrators are super users of their asset library but cannot make other users into Asset Library Administrators.</Description><Description language-id=\"zh_CN\">资产库管理员是其资产库的超级用户，但不能使其他用户成为资产库管理员。</Description><Description language-id=\"es_ES\">Los administradores del repositorio son superusuarios de su repositorio, pero no pueden convertir a otros usuarios en administradores del repositorio.</Description><Description language-id=\"nl_NL\">Assetbibliotheekbeheerders zijn supergebruikers van hun assetbibliotheek, maar kunnen geen assetbibliotheekbeheerders maken van andere gebruikers.</Description></root>', 5, NULL), (0, 0, 'fdefe995-4bd0-1ab8-5628-c43dd7aa9505', 20140, 20097, 20101, NULL, '2022-12-22 04:00:36.574000', '2022-12-22 04:00:36.574000', 20065, 20140, 'Asset Library Connected Site Member', NULL, '', 5, NULL), (0, 0, '0c18603c-9eea-fdcf-1156-c3d940e7a491', 20141, 20097, 20101, NULL, '2022-12-22 04:00:36.576000', '2022-12-22 04:00:36.576000', 20065, 20141, 'Asset Library Content Reviewer', NULL, '', 5, NULL), (0, 0, 'bfcbeab1-3e7a-5e93-98f9-003992ef4ecb', 20142, 20097, 20101, NULL, '2022-12-22 04:00:36.579000', '2022-12-22 04:00:36.579000', 20065, 20142, 'Asset Library Member', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Alla användare som tillhör ett tillgångsbibliotek har den här rollen i det tillgångsbiblioteket.</Description><Description language-id=\"pt_BR\">Todos os usuários que pertencem a uma biblioteca de ativos possuem esta função nessa biblioteca de ativos.</Description><Description language-id=\"ja_JP\">アセットライブラリに属している全ユーザーは、このアセットライブラリでこのロールを割り当てられています。</Description><Description language-id=\"fr_FR\">Tous les utilisateurs qui appartiennent à un dépôt ont ce rôle au sein de ce dépôt.</Description><Description language-id=\"hu_HU\">Egy adattárhoz tartozó összes felhasználó ezzel a szerepkörrel rendelkezik az adattáron belül.</Description><Description language-id=\"de_DE\">Alle Benutzer, die zu einem Repository gehören, haben diese Rolle innerhalb dieses Repositorys inne.</Description><Description language-id=\"ca_ES\">Tots els usuaris que pertanyin a una biblioteca de continguts tenen aquest rol en aquesta biblioteca de continguts.</Description><Description language-id=\"ar_SA\">جميع المستخدمين الذين ينتمون إلى مكتبة أصول ما لديهم هذا الدور داخل مكتبة الأصول تلك.</Description><Description language-id=\"fi_FI\">Kaikilla käyttäjillä, jotka kuuluvat sisältökirjastoon, on tämä rooli kyseisen sisältökirjaston sisällä.</Description><Description language-id=\"en_US\">All users who belong to an asset library have this role within that asset library.</Description><Description language-id=\"zh_CN\">属于资产库的所有用户都具有该资产库中的此角色。</Description><Description language-id=\"es_ES\">Todos los usuarios que pertenecen a un repositorio tienen este rol en ese repositorio.</Description><Description language-id=\"nl_NL\">Alle gebruikers die bij een assetbibliotheek horen, hebben deze rol in die assetbibliotheek.</Description></root>', 5, NULL), (0, 0, 'a9ad1b75-e508-b47d-1c70-2c3ca0c1e87e', 20143, 20097, 20101, NULL, '2022-12-22 04:00:36.582000', '2022-12-22 04:00:36.582000', 20065, 20143, 'Asset Library Owner', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Administratörer av tillgångsbibliotek är superanvändare av sitt tillgångsbibliotek och kan tilldela roller i tillgångsbiblioteket till användare.</Description><Description language-id=\"pt_BR\">Os Proprietários de Bibliotecas de Ativo são super usuários de suas bibliotecas de ativo e podem atribuir funções da biblioteca de ativos a outros usuários.</Description><Description language-id=\"ja_JP\">アセットライブラリの所有者は、それぞれのアセットライブラリのスーパーユーザーであり、ユーザーにアセットライブラリのロールを割り当てることができます。</Description><Description language-id=\"fr_FR\">Les propriétaires d\'un dépôt sont des super utilisateurs de ce dépôt et peuvent affecter des rôles à des utilisateurs.</Description><Description language-id=\"hu_HU\">Az adattár tulajdonosai adattáruk magasabbrendű felhasználói, és adattár szerepköröket rendelhetnek hozzá más felhasználókhoz.</Description><Description language-id=\"de_DE\">Besitzer von Assetbibliotheken sind Administratoren ihrer Assetbibliothek und können Benutzern Assetbibliothek-Rollen zuweisen.</Description><Description language-id=\"ca_ES\">Els propietaris de la biblioteca de continguts són superusuaris de la seva biblioteca de continguts, i poden assignar rols de la biblioteca de continguts als usuaris.</Description><Description language-id=\"ar_SA\">مالكو مكتبة الأصول هم مستخدمون متميزون لمكتبة الأصول الخاصة بهم ويمكنهم تعيين أدوار مكتبة الأصول إلى المستخدمين.</Description><Description language-id=\"fi_FI\">Sisältökirjaston Omistajat ovat sisältökirjastonsa superkäyttäjiä, ja voivat liittää sisältökirjaston rooleja käyttäjille.</Description><Description language-id=\"en_US\">Asset Library Owners are super users of their asset library and can assign asset library roles to users.</Description><Description language-id=\"zh_CN\">资产库所有者是其资产库的超级用户，且可以将资产库角色分配给用户。</Description><Description language-id=\"es_ES\">Los propietarios de repositorio son superusuarios de su repositorio y pueden asignar roles de repositorio a otros usuarios.</Description><Description language-id=\"nl_NL\">Assetbibliotheekeigenaars zijn supergebruikers van hun assetbibliotheek en kunnen assetbibliotheekrollen toewijzen aan gebruikers.</Description></root>', 5, NULL), (2, 0, '0725522b-d263-d553-ce09-621583212e1b', 41732, 20097, 20125, 'Test Test', '2022-12-22 04:01:05.433000', '2022-12-22 04:01:05.587000', 41729, 41733, 'Account Administrator', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Title language-id=\"en_US\">Account Administrator</Title></root>', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Account Administrators are super users of their account.</Description></root>', 6, NULL), (1, 0, '9241e702-7e2c-0fcf-4b11-066c84913baa', 41734, 20097, 20125, 'Test Test', '2022-12-22 04:01:05.501000', '2022-12-22 04:01:05.503000', 41729, 41735, 'Buyer', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Title language-id=\"en_US\">Buyer</Title></root>', '', 6, NULL), (1, 0, 'adb94d58-9d1d-c467-de49-43a0ca416355', 41736, 20097, 20125, 'Test Test', '2022-12-22 04:01:05.535000', '2022-12-22 04:01:05.538000', 41729, 41737, 'Order Manager', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Title language-id=\"en_US\">Order Manager</Title></root>', '', 6, NULL), (1, 0, '4d0a1d2c-9de5-385b-37b7-eec24c6ca780', 41738, 20097, 20101, NULL, '2022-12-22 04:01:05.582000', '2022-12-22 04:01:05.584000', 41729, 41739, 'Account Member', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">All users who belong to an account have this role within that account.</Description></root>', 6, NULL), (0, 0, '7e421d17-02ad-dde3-c51b-ef31ef6b8e57', 41740, 20097, 20101, NULL, '2022-12-22 04:01:05.595000', '2022-12-22 04:01:05.595000', 20065, 41740, 'Account Manager', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Account Managers who belong to an organization can administer all accounts associated to that organization.</Description></root>', 3, NULL), (0, 0, '827ec67a-40c3-9f7a-f948-b957daf060e0', 43016, 20097, 20101, NULL, '2022-12-22 04:01:13.048000', '2022-12-22 04:01:13.048000', 20065, 43016, 'Portal Content Reviewer', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">This is an autogenerated role from the workflow definition.</Description></root>', 1, NULL), (0, 0, '68b6efaf-c84e-de03-bd03-94bd5a6dc8de', 43019, 20097, 20101, NULL, '2022-12-22 04:01:13.055000', '2022-12-22 04:01:13.055000', 20065, 43019, 'Organization Content Reviewer', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">This is an autogenerated role from the workflow definition.</Description></root>', 3, NULL), (0, 0, '905895f6-b931-1746-d774-3c9cabbb19ad', 43021, 20097, 20101, NULL, '2022-12-22 04:01:13.058000', '2022-12-22 04:01:13.058000', 20065, 43021, 'Site Content Reviewer', NULL, '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">This is an autogenerated role from the workflow definition.</Description></root>', 2, NULL);
