  `allowedServiceSignatures` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `defaultSAPEntry` tinyint NULL DEFAULT NULL,
  `enabled` tinyint NULL DEFAULT NULL,
  `name` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `title` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  PRIMARY KEY (`sapEntryId`) USING BTREE,
  INDEX `IX_6D669D6F`(`companyId`, `defaultSAPEntry`) USING BTREE,
  INDEX `IX_90740311`(`companyId`, `name`) USING BTREE,
  INDEX `IX_AAAEBA0A`(`uuid_`, `companyId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci;

