INSERT INTO `SXPElement` (`mvccVersion`, `uuid_`, `externalReferenceCode`, `sxpElementId`, `companyId`, `userId`, `userName`, `createDate`, `modifiedDate`, `description`, `elementDefinitionJSON`, `hidden_`, `readOnly`, `schemaVersion`, `title`, `type_`, `version`, `status`) VALUES (0, '2b7e6f07-313a-2daa-5f16-d3769217405a', 'BOOST_ALL_KEYWORDS_MATCH', 1, 20097, 20101, NULL, '2022-12-22 04:02:24.080000', '2022-12-22 04:02:24.080000', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Description language-id=\"en_US\">Boost contents if the search keywords match in the given fields.</Description><Description language-id=\"ja_JP\">検索キーワードが指定されたフィールドに一致する場合、コンテンツをブーストする</Description></root>', '{\"category\": \"boost\", \"configuration\": {\"queryConfiguration\": {\"queryEntries\": [{\"clauses\": [{\"context\": \"query\", \"occur\": \"should\", \"query\": {\"multi_match\":{\"boost\":\"${configuration.boost}\",\"fields\":\"${configuration.fields}\",\"type\":\"${configuration.type}\",\"operator\":\"and\",\"query\":\"${configuration.keywords}\"}}}]}]}}, \"icon\": \"thumbs-up\", \"uiConfiguration\": {\"fieldSets\": [{\"fields\": [{\"defaultValue\": [{\"field\":\"localized_title\",\"locale\":\"${context.language_id}\",\"boost\":2},{\"field\":\"content\",\"locale\":\"${context.language_id}\",\"boost\":1}], \"label\": \"Field\", \"name\": \"fields\", \"type\": \"fieldMappingList\", \"typeOptions\": {\"boost\": true}}, {\"defaultValue\": \"best_fields\", \"label\": \"Match Type\", \"name\": \"type\", \"type\": \"select\", \"typeOptions\": {\"options\": [{\"label\": \"Best Fields\", \"value\": \"best_fields\"}, {\"label\": \"Most Fields\", \"value\": \"most_fields\"}, {\"label\": \"Cross Fields\", \"value\": \"cross_fields\"}, {\"label\": \"Phrase\", \"value\": \"phrase\"}, {\"label\": \"Phrase Prefix\", \"value\": \"phrase_prefix\"}, {\"label\": \"Boolean Prefix\", \"value\": \"bool_prefix\"}]}}, {\"defaultValue\": 10, \"label\": \"Boost\", \"name\": \"boost\", \"type\": \"number\", \"typeOptions\": {\"min\": 0}}, {\"helpText\": \"If this is set, the search terms entered in the search bar will be replaced by this value.\", \"label\": \"Text to Match\", \"name\": \"keywords\", \"type\": \"keywords\", \"typeOptions\": {\"required\": false}}]}]}}', 0, 1, '1.0', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Title language-id=\"en_US\">Boost All Keywords Match</Title><Title language-id=\"ja_JP\">全マッチキーワードのブースト</Title></root>', 0, '1.0', 0), (0, '776b8ccd-e3ac-566a-b107-6e838097ecaf', 'BOOST_ASSET_TYPE', 2, 20097, 20101, NULL, '2022-12-22 04:02:24.129000', '2022-12-22 04:02:24.129000', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Description language-id=\"en_US\">Boost the given asset type.</Description><Description language-id=\"ja_JP\">指定されたアセットタイプをブーストする</Description></root>', '{\"category\": \"boost\", \"configuration\": {\"queryConfiguration\": {\"queryEntries\": [{\"clauses\": [{\"context\": \"query\", \"occur\": \"should\", \"query\": {\"term\":{\"entryClassName\":{\"value\":\"${configuration.entry_class_name}\",\"boost\":\"${configuration.boost}\"}}}}]}]}}, \"icon\": \"thumbs-up\", \"uiConfiguration\": {\"fieldSets\": [{\"fields\": [{\"label\": \"Asset Type\", \"name\": \"entry_class_name\", \"type\": \"searchableType\"}, {\"defaultValue\": 10, \"label\": \"Boost\", \"name\": \"boost\", \"type\": \"number\", \"typeOptions\": {\"min\": 0}}]}]}}', 0, 1, '1.0', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Title language-id=\"en_US\">Boost Asset Type</Title><Title language-id=\"ja_JP\">アセットタイプのブースト</Title></root>', 0, '1.0', 0), (0, 'c79316bd-a5c0-1184-96c2-256a35709042', 'BOOST_CONTENTS_FOR_THE_CURRENT_LANGUAGE', 3, 20097, 20101, NULL, '2022-12-22 04:02:24.150000', '2022-12-22 04:02:24.150000', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Description language-id=\"en_US\">Boost contents having a default language matching the current session language.</Description><Description language-id=\"ja_JP\">現在のセッション言語と同じデフォルト言語を持つコンテンツをブーストする</Description></root>', '{\"category\": \"boost\", \"configuration\": {\"queryConfiguration\": {\"queryEntries\": [{\"clauses\": [{\"context\": \"query\", \"occur\": \"should\", \"query\": {\"bool\":{\"must\":[{\"terms\":{\"entryClassName\":[\"com.liferay.portal.kernel.model.Layout\",\"com.liferay.journal.model.JournalArticle\"]}},{\"term\":{\"defaultLanguageId\":{\"value\":\"${context.language_id}\",\"boost\":\"${configuration.boost}\"}}}]}}}]}]}}, \"icon\": \"thumbs-up\", \"uiConfiguration\": {\"fieldSets\": [{\"fields\": [{\"defaultValue\": 20, \"label\": \"Boost\", \"name\": \"boost\", \"type\": \"number\", \"typeOptions\": {\"min\": 0}}]}]}}', 0, 1, '1.0', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Title language-id=\"en_US\">Boost Contents for the Current Language</Title><Title language-id=\"ja_JP\">現在の言語でブースト</Title></root>', 0, '1.0', 0), (0, 'c5ca0c89-d40c-c4e1-a23f-cccb3b81ae87', 'BOOST_CONTENTS_IN_A_CATEGORY', 4, 20097, 20101, NULL, '2022-12-22 04:02:24.171000', '2022-12-22 04:02:24.171000', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Description language-id=\"en_US\">Boost and promote contents in a given category.</Description><Description language-id=\"ja_JP\">特定のカテゴリーに属するコンテンツのブースト。</Description></root>', '{\"category\": \"boost\", \"configuration\": {\"queryConfiguration\": {\"queryEntries\": [{\"clauses\": [{\"context\": \"query\", \"occur\": \"should\", \"query\": {\"terms\":{\"boost\":\"${configuration.boost}\",\"assetCategoryIds\":\"${configuration.asset_category_ids}\"}}}]}]}}, \"icon\": \"thumbs-up\", \"uiConfiguration\": {\"fieldSets\": [{\"fields\": [{\"label\": \"Asset Category IDs\", \"name\": \"asset_category_ids\", \"type\": \"multiselect\"}, {\"defaultValue\": 10, \"label\": \"Boost\", \"name\": \"boost\", \"type\": \"number\", \"typeOptions\": {\"min\": 0}}]}]}}', 0, 1, '1.0', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Title language-id=\"en_US\">Boost Contents in a Category</Title><Title language-id=\"ja_JP\">あるカテゴリ内のコンテンツをブースト</Title></root>', 0, '1.0', 0), (0, '576998d8-df6b-914c-0ba7-11c212c12551', 'BOOST_CONTENTS_IN_A_CATEGORY_BY_KEYWORD_MATCH', 5, 20097, 20101, NULL, '2022-12-22 04:02:24.199000', '2022-12-22 04:02:24.199000', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Description language-id=\"en_US\">Boost contents in a category if the user\'s search keywords contain any of the given keywords.</Description><Description language-id=\"ja_JP\">ユーザーの検索キーワードが与えられたキーワードのいずれかを含む場合、カテゴリ内のコンテンツをブーストする</Description></root>', '{\"category\": \"conditional\", \"configuration\": {\"queryConfiguration\": {\"queryEntries\": [{\"clauses\": [{\"context\": \"query\", \"occur\": \"should\", \"query\": {\"term\":{\"assetCategoryIds\":{\"value\":\"${configuration.asset_category_id}\",\"boost\":\"${configuration.boost}\"}}}}], \"condition\": {\"contains\": {\"parameterName\": \"keywords\", \"value\": \"${configuration.keywords}\"}}}]}}, \"icon\": \"thumbs-up\", \"uiConfiguration\": {\"fieldSets\": [{\"fields\": [{\"label\": \"Asset Category ID\", \"name\": \"asset_category_id\", \"type\": \"number\"}, {\"label\": \"Keywords\", \"name\": \"keywords\", \"type\": \"multiselect\"}, {\"defaultValue\": 10, \"label\": \"Boost\", \"name\": \"boost\", \"type\": \"number\", \"typeOptions\": {\"min\": 0}}]}]}}', 0, 1, '1.0', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Title language-id=\"en_US\">Boost Contents in a Category by Keyword Match</Title><Title language-id=\"ja_JP\">キーワードマッチによるカテゴリー内コンテンツのブースト</Title></root>', 0, '1.0', 0), (0, 'e7c3a12c-ae59-3aca-a950-8963f4283ee2', 'BOOST_CONTENTS_IN_A_CATEGORY_FOR_A_PERIOD_OF_TIME', 6, 20097, 20101, NULL, '2022-12-22 04:02:24.225000', '2022-12-22 04:02:24.225000', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Description language-id=\"en_US\">Boost contents in a category for the given period of time.</Description><Description language-id=\"ja_JP\">指定期間でカテゴリ内のコンテンツをブーストする</Description></root>', '{\"category\": \"conditional\", \"configuration\": {\"queryConfiguration\": {\"queryEntries\": [{\"clauses\": [{\"context\": \"query\", \"occur\": \"should\", \"query\": {\"term\":{\"assetCategoryIds\":{\"value\":\"${configuration.asset_category_id}\",\"boost\":\"${configuration.boost}\"}}}}], \"condition\": {\"range\": {\"format\": \"yyyyMMdd\", \"gte\": \"${configuration.start_date}\", \"lte\": \"${configuration.end_date}\", \"parameterName\": \"time.current_date\"}}}]}}, \"icon\": \"thumbs-up\", \"uiConfiguration\": {\"fieldSets\": [{\"fields\": [{\"label\": \"Asset Category ID\", \"name\": \"asset_category_id\", \"type\": \"number\"}, {\"label\": \"Date: From\", \"name\": \"start_date\", \"type\": \"date\", \"typeOptions\": {\"format\": \"YYYYMMDD\"}}, {\"label\": \"Date: To\", \"name\": \"end_date\", \"type\": \"date\", \"typeOptions\": {\"format\": \"YYYYMMDD\"}}, {\"defaultValue\": 10, \"label\": \"Boost\", \"name\": \"boost\", \"type\": \"number\", \"typeOptions\": {\"min\": 0}}]}]}}', 0, 1, '1.0', '<?xml version=\'1.0\' encoding=\'UTF-8\'?><root available-locales=\"en_US,ja_JP\" default-locale=\"en_US\"><Title language-id=\"en_US\">Boost Contents in a Category for a Period of Time</Title><Title language-id=\"ja_JP\">一定期間内のカテゴリ内コンテンツをブーストする</Title></root>', 0, '1.0', 0), (0, '6ea31f46-a9dc-7b5d-c816-3d4fafce4c6d', 'BOOST_CONTENTS_IN_A_CATEGORY_FOR_USER_SEGMEN